// DRY violation - repeated logic
fn process_user_a(user: &User) -> Result {
    if user.is_active() && user.has_permission() {
        Ok(format!("User {} is valid", user.name))
    } else {
        Err("Invalid user".into())
    }
}

fn process_user_b(user: &User) -> Result {
    if user.is_active() && user.has_permission() {
        Ok(format!("User {} is valid", user.name))
    } else {
        Err("Invalid user".into())
    }
}

example.after:
// DRY - extracted common logic
fn validate_user(user: &User) -> Result {
    if user.is_active() && user.has_permission() {
        Ok(format!("User {} is valid", user.name))
    } else {
        Err("Invalid user".into())
    }
}

fn process_user_a(user: &User) -> Result {
    validate_user(user)
}

fn process_user_b(user: &User) -> Result {
    validate_user(user)
}

example.before:
// Violates Open/Closed - requires modification for new types
fn process_data(data: Data) -> String {
    match data {
        Data::Text(s) => format!("Text: {}", s),
        Data::Number(n) => format!("Number: {}", n),
        // Must modify here for new variants
    }
}

example.after:
// Open/Closed - extensible without modification
trait Processable {
    fn process(&self) -> String;
}

impl Processable for String {
    fn process(&self) -> String {
        format!("Text: {}", self)
    }
}

impl Processable for i64 {
    fn process(&self) -> String {
        format!("Number: {}", self)
    }
}

fn process_data(data: &T) -> String {
    data.process()
}

example.before:
// Complex constructor - hard to read
fn create_config(
    host: String,
    port: u16,
    timeout: Option,
    retries: Option,
    tls: Option,
) -> Config {
    Config {
        host,
        port,
        timeout: timeout.unwrap_or(30),
        retries: retries.unwrap_or(3),
        tls: tls.unwrap_or(true),
    }
}

example.after:
// Builder pattern - clear and flexible
struct ConfigBuilder {
    host: String,
    port: u16,
    timeout: u64,
    retries: u32,
    tls: bool,
}

impl ConfigBuilder {
    fn new(host: String, port: u16) -> Self {
        Self {
            host,
            port,
            timeout: 30,
            retries: 3,
            tls: true,
        }
    }

    fn timeout(mut self, timeout: u64) -> Self {
        self.timeout = timeout;
        self
    }

    fn retries(mut self, retries: u32) -> Self {
        self.retries = retries;
        self
    }

    fn tls(mut self, tls: bool) -> Self {
        self.tls = tls;
        self
    }

    fn build(self) -> Config {
        Config {
            host: self.host,
            port: self.port,
            timeout: self.timeout,
            retries: self.retries,
            tls: self.tls,
        }
    }
}

example.before:
// Imperative loop
fn filter_and_map(numbers: &[i32]) -> Vec {
    let mut result = Vec::new();
    for n in numbers {
        if n > 0 {
            result.push(n * 2);
        }
    }
    result
}

example.after:
// Iterator chain - more idiomatic
fn filter_and_map(numbers: &[i32]) -> Vec {
    numbers
        .iter()
        .filter(|&&n| n > 0)
        .map(|&n| n * 2)
        .collect()
}

example.before:
// Type confusion risk
fn connect(host: String, port: u16) { /* ... */ }

fn main() {
    connect("localhost".to_string(), 8080);
    // Easy to accidentally swap arguments
}

example.after:
// Type-safe newtypes
#[derive(Debug, Clone)]
struct Host(String);

#[derive(Debug, Clone)]
struct Port(u16);

fn connect(host: Host, port: Port) { /* ... */ }

fn main() {
    connect(Host("localhost".to_string()), Port(8080));
    // Compiler catches swapped arguments
}

example.before:
// Nested match statements
fn process(input: &str) -> Result {
    let parsed = match parse(input) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    let validated = match validate(parsed) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    Ok(format!("{:?}", validated))
}

example.after:
// Result combinators - cleaner
fn process(input: &str) -> Result {
    parse(input)
        .and_then(validate)
        .map(|v| format!("{:?}", v))
}
